  1→import { db } from '@/lib/db'
  2→import { NextRequest, NextResponse } from 'next/server'
  3→import { parseExcelFile } from '@/lib/excel-parser'
  4→
  5→export async function GET(request: NextRequest) {
  6→  try {
  7→    const { searchParams } = new URL(request.url)
  8→    const status = searchParams.get('status')
  9→    const search = searchParams.get('search')
 10→
 11→    const where: Record<string, unknown> = {}
 12→    if (status) where.status = status
 13→    if (search) {
 14→      where.OR = [
 15→        { name: { contains: search } },
 16→        { customerName: { contains: search } },
 17→      ]
 18→    }
 19→
 20→    const projects = await db.project.findMany({
 21→      where,
 22→      orderBy: { createdAt: 'desc' },
 23→      include: {
 24→        items: {
 25→          select: {
 26→            id: true,
 27→            price: true,
 28→            quantity: true,
 29→            status: true,
 30→          },
 31→        },
 32→        _count: {
 33→          select: { items: true },
 34→        },
 35→      },
 36→    })
 37→
 38→    return NextResponse.json(projects)
 39→  } catch (error) {
 40→    console.error('Projects list error:', error)
 41→    return NextResponse.json({ error: 'Failed to fetch projects' }, { status: 500 })
 42→  }
 43→}
 44→
 45→export async function POST(request: NextRequest) {
 46→  try {
 47→    const body = await request.json()
 48→    const { name, description, customerName, fileData, fileName } = body
 49→
 50→    if (!name || !name.trim()) {
 51→      return NextResponse.json({ error: 'Project name is required' }, { status: 400 })
 52→    }
 53→
 54→    // Если переданы файловые данные (от Telegram Bot), парсим Excel
 55→    if (fileData && typeof fileData === 'string') {
 56→      try {
 57→        const buffer = Buffer.from(fileData, 'base64')
 58→        const parsedItems = parseExcelFile(buffer.buffer as ArrayBuffer)
 59→
 60→        if (parsedItems.length === 0) {
 61→          return NextResponse.json({ error: 'Excel файл пуст или не содержит распознаваемых позиций' }, { status: 400 })
 62→        }
 63→
 64→        // Создаём проект с позициями из Excel
 65→        const project = await db.project.create({
 66→          data: {
 67→            name: name.trim(),
 68→            description: description?.trim() || '',
 69→            customerName: customerName?.trim() || '',
 70→            fileName: fileName || '',
 71→            items: {
 72→              create: parsedItems.map((item) => ({
 73→                name: item.name,
 74→                article: item.article,
 75→                category: item.category,
 76→                quantity: item.quantity,
 77→                unit: item.unit,
 78→                price: item.price,
 79→                notes: item.notes,
 80→                rowNumber: item.rowNumber,
 81→                status: 'pending' as const,
 82→              })),
 83→            },
 84→          },
 85→          include: {
 86→            _count: { select: { items: true } },
 87→          },
 88→        })
 89→
 90→        return NextResponse.json(project, { status: 201 })
 91→      } catch (parseError) {
 92→        console.error('Excel parse error:', parseError)
 93→        return NextResponse.json({ error: `Ошибка парсинга Excel: ${parseError instanceof Error ? parseError.message : 'неизвестная ошибка'}` }, { status: 400 })
 94→      }
 95→    }
 96→
 97→    // Обычное создание проекта (без файла)
 98→    const project = await db.project.create({
 99→      data: {
100→        name: name.trim(),
101→        description: description?.trim() || '',
102→        customerName: customerName?.trim() || '',
103→      },
104→      include: {
105→        _count: { select: { items: true } },
106→      },
107→    })
108→
109→    return NextResponse.json(project, { status: 201 })
110→  } catch (error) {
111→    console.error('Project create error:', error)
112→    return NextResponse.json({ error: 'Failed to create project' }, { status: 500 })
113→  }
114→}
